export function process(payload) {
  // Сообщение устройства приходит JSON-строкой.
  const data = JSON.parse(payload);
  const result = {};

  // Числовые показатели: null и отсутствующие поля пропускаем,
  // чтобы не затирать предыдущее значение (props.setUndefinedParamTo = "prev").
  const numbers = ["temperature", "tds", "turbidity_raw", "clarity_percent",
                   "air_temperature", "air_humidity", "brightness_level"];
  for (const key of numbers) {
    if (typeof data[key] === "number" && Number.isFinite(data[key])) {
      result[key] = data[key];
    }
  }

  // Выходы приходят числами 0/1, в модели это boolean.
  for (const key of ["output1", "output2", "output3"]) {
    if (data[key] === 0 || data[key] === 1) {
      result[key] = data[key] === 1;
    }
  }

  return result;
}
